 INSERT INTO operations_report_conversions VALUES('OFFLOAD','00000000-0000-4000-8000-000000000040','BACKLOAD','00000000-0000-4000-8000-000000000080','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000012');
 BEGIN PERFORM delete_transaction_with_cleanup_v1('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000001'); RAISE EXCEPTION 'conversion guard failed'; EXCEPTION WHEN SQLSTATE '55000' THEN NULL; END;
 DELETE FROM operations_report_conversions;
 r:=delete_transaction_with_cleanup_v1('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000001');
 IF r->>'state'<>'PENDING_STORAGE' OR jsonb_array_length(r->'storage_objects')<>1 THEN RAISE EXCEPTION 'cleanup manifest failed'; END IF;
 IF jsonb_array_length(r->'snapshot'->'offload_items')<>1 OR jsonb_array_length(r->'snapshot'->'flex_cells')<>1 THEN RAISE EXCEPTION 'snapshot failed'; END IF;
 IF (SELECT count(*) FROM trip_stops)<>2 OR (SELECT count(*) FROM trip_truck_assignments)<>1 OR (SELECT count(*) FROM trips)<>1 OR NOT EXISTS(SELECT 1 FROM trip_stops WHERE archived_at IS NOT NULL) THEN RAISE EXCEPTION 'sibling/shared/archive isolation failed'; END IF;
 IF EXISTS(SELECT 1 FROM offloads) OR EXISTS(SELECT 1 FROM offload_items) OR EXISTS(SELECT 1 FROM report_receipts) OR EXISTS(SELECT 1 FROM pod_records) OR EXISTS(SELECT 1 FROM flex_cells) OR EXISTS(SELECT 1 FROM trip_line_items) THEN RAISE EXCEPTION 'owned deletion failed'; END IF;
 IF r->>'id' IS DISTINCT FROM delete_transaction_with_cleanup_v1('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000001')->>'id' THEN RAISE EXCEPTION 'retry identity failed'; END IF;
 PERFORM delete_transaction_with_cleanup_v1('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000001');
 PERFORM delete_transaction_with_cleanup_v1('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000013','00000000-0000-4000-8000-000000000001');
 IF EXISTS(SELECT 1 FROM trips) OR EXISTS(SELECT 1 FROM trip_truck_assignments) THEN RAISE EXCEPTION 'last parent cleanup failed'; END IF;
 IF has_function_privilege('authenticated','delete_transaction_with_cleanup_v1(uuid,uuid,uuid)','EXECUTE') OR has_table_privilege('authenticated','transaction_deletion_jobs','SELECT') THEN RAISE EXCEPTION 'private ACL failed'; END IF;
 IF has_table_privilege('service_role','transaction_deletion_jobs','DELETE') OR has_column_privilege('service_role','transaction_deletion_jobs','snapshot','UPDATE') THEN RAISE EXCEPTION 'journal immutability failed'; END IF;
END; $$;
